using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEditor.Build.Reporting;
[InitializeOnLoad]public static class AtelierQA {
 static double next;static List<string> checks=new List<string>();static int sparksBefore;static float travelBefore;static Action pending;
 static AtelierQA(){EditorApplication.update+=Poll;}
 static void Check(bool result,string label){checks.Add((result?"PASS ":"FAIL ")+label);File.WriteAllLines(AtelierEditor.Root+"/Reports/qa-checks.txt",checks);if(!result)throw new Exception(label);}
 public static void Run(){checks.Clear();File.WriteAllText(AtelierEditor.Root+"/Reports/qa-checks.txt","");EditorSceneManager.OpenScene(AtelierEditor.Scene);SessionState.SetBool("Atelier.QA",true);SessionState.SetInt("Atelier.QAStep",0);var gv=EditorWindow.GetWindow(typeof(Editor).Assembly.GetType("UnityEditor.GameView"));gv.Show();gv.maximized=true;gv.Focus();EditorApplication.EnterPlaymode();next=EditorApplication.timeSinceStartup+5;}
 static void Shot(string name){ScreenCapture.CaptureScreenshot(AtelierEditor.Root+"/Reports/"+name+".png");}
 static void Poll(){if(!SessionState.GetBool("Atelier.QA",false)||!EditorApplication.isPlaying||EditorApplication.isCompiling)return;EditorApplication.QueuePlayerLoopUpdate();UnityEditorInternal.InternalEditorUtility.RepaintAllViews();if(EditorApplication.timeSinceStartup<next)return;next=EditorApplication.timeSinceStartup+1.5;var x=UnityEngine.Object.FindObjectOfType<AtelierExperience>();if(!x||!x.Ready||!x.assembly.canvas||Time.frameCount<5)return;var w=x.assembly;var e=x.engine;int step=SessionState.GetInt("Atelier.QAStep",0);try{switch(step){
 case 0:Check(w.Complete,"Initial completed locomotive");Check(w.pieces.Length==45,"45 detachable assemblies preserved");Check(!w.canvas.enabled,"Legacy menu canvas hidden");Check(x.floatingStatus&&x.floatingStatus.GetComponent<Canvas>().renderMode==RenderMode.WorldSpace,"Status readout belongs to tabletop space");Check(x.floatingStatus.GetComponentInChildren<UnityEngine.UI.Button>()==null,"Floating readout has no menu buttons");Check(!e.studioCamera.rect.Equals(new Rect(0,0,.725f,1)),"Full width workshop view");Check(UnityEngine.Object.FindObjectsOfType<AtelierControl>().Count(c=>c.action==AtelierAction.Throttle)==1,"Physical throttle exists");Check(x.secondLamp&&x.presentation.headlight,"Two independently lit front lanterns");x.SetThrottle(.5f);break;
 case 1:Check(e.running&&!e.travel,"Mechanical throttle drives stationary demonstration");Check(Mathf.Abs(Mathf.DeltaAngle(x.throttlePivot.localEulerAngles.x,x.precisionDesk?-20:0))<5,"Throttle quadrant responds");Check(w.effects.smoke.particleCount>0,"Chimney steam visible");x.Activate(AtelierAction.Brake);break;
 case 2:Check(!e.running,"Mechanical brake stops stationary motion");x.Activate(AtelierAction.Observation);x.SetThrottle(1);travelBefore=e.travelled;next=EditorApplication.timeSinceStartup+1.2;break;
 case 3:Check(e.travelled>travelBefore+.1f&&x.drive.signedRpm>10,"Forward lever drives along tabletop rails");sparksBefore=e.GetComponent<LocomotiveBrakeSparksV11>().emitted;x.Activate(AtelierAction.Brake);next=EditorApplication.timeSinceStartup+.3;break;
 case 4:Check(e.GetComponent<LocomotiveBrakeSparksV11>().emitted>sparksBefore,"Abrupt braking emits wheel rail sparks");Shot("05-braking");next=EditorApplication.timeSinceStartup+2;break;
 case 5:Check(Mathf.Abs(x.drive.signedRpm)<.02f,"Braking settles to zero speed");x.SetDirection(-1);x.SetThrottle(.7f);next=EditorApplication.timeSinceStartup+1.2;break;
 case 6:Check(x.drive.signedRpm<0,"Reverser drives backward");x.Activate(AtelierAction.Brake);next=EditorApplication.timeSinceStartup+2;break;
 case 7:x.drive.ResetDrive();e.ApplyPose();x.travelling=false;var doors=e.GetComponent<LocomotiveDoorsV11>();doors.Toggle(e.doors[0].GetComponent<LocomotivePart>());break;
 case 8:var d=e.GetComponent<LocomotiveDoorsV11>();Check(d.open[0]&&!d.open[1]&&d.angles[0]>59,"Cab doors operate independently");d.CloseAll();d.Toggle(e.parts.First(p=>p.partId=="M02-D"));break;
 case 9:Check(e.GetComponent<LocomotiveDoorsV11>().fireAngle>77,"Firebox door opens on its hinge");e.GetComponent<LocomotiveDoorsV11>().CloseAll();foreach(string key in new[]{"rheadlamp","lheadlamp","boiler","cab","rtank","frontbeam","firebox"}){int i=Array.FindIndex(w.pieces,p=>p.key==key);Check(w.TakeInstalled(i),"Detach "+key);w.MoveGrab(new Vector3(8,4,5));w.ReleaseGrab();w.LeaveInSpace();var loose=w.looseObjects[i];Check(loose,"Released part rests on workbench "+key);var rs=loose.GetComponentsInChildren<MeshRenderer>().Where(r=>r.enabled).ToArray();var contact=rs[0].bounds;foreach(var r in rs.Skip(1))contact.Encapsulate(r.bounds);Check(Mathf.Abs(contact.min.y+.465f)<.018f,"Tabletop contact height "+key);Check(w.BeginGrab(i),"Grab again "+key);w.MoveGrab(w.Socket);Check(w.ReleaseGrab(),"Reinstall "+key);}Check(w.Complete,"All checked groups return correctly");w.LeaveInSpace();x.Activate(AtelierAction.ResetGuard);x.Activate(AtelierAction.Assembly);x.HoldReset(1.3f);break;
 case 10:Check(w.InstalledCount==0,"Physical reset starts assembly");Check(x.trayModels.Count(t=>t)>0,"Real parts tray presents available modules");for(int i=0;i<w.pieces.Length;i++){Check(w.BeginGrab(i),"Grab part "+i);w.MoveGrab(w.Socket+Vector3.forward*2);w.MoveGrab(w.Socket);w.UpdatePlacementHints();Check(w.ghost&&!w.ghost.activeSelf,"Overlap ghost hidden "+i);Check(w.ReleaseGrab(),"Snap part "+i);}w.LeaveInSpace();Check(w.Complete,"Full assembly cycle complete");x.SetThrottle(.4f);x.Activate(AtelierAction.Cutaway);next=EditorApplication.timeSinceStartup+5;break;
 case 11:Check(e.principle,"Mechanical section switch shows cutaway");Check(e.GetComponent<LocomotiveDynamicsV10>().emittedBubbles>0,"Boiling water present");Check(e.GetComponent<LocomotiveDynamicsV10>().condensation.particleCount>0,"Condensation present");Shot("06-verified-cutaway");break;
 case 12:x.Activate(AtelierAction.Cutaway);x.Activate(AtelierAction.Brake);x.SetView(0);w.effects.fireEnabled=true;var q=e.GetComponent<LocomotiveXRQuality>();q.Sample();var renderer=UnityEngine.Object.FindObjectsOfType<MeshRenderer>();long tris=renderer.Where(r=>r.enabled&&r.GetComponent<MeshFilter>()&&r.GetComponent<MeshFilter>().sharedMesh).Sum(r=>{var m=r.GetComponent<MeshFilter>().sharedMesh;long sum=0;for(int j=0;j<m.subMeshCount;j++)sum+=m.GetIndexCount(j)/3;return sum;});File.WriteAllText(AtelierEditor.Root+"/Reports/scene-metrics.txt","Visible mesh triangles: "+tris+"\nDraw calls (Editor): "+UnityEditor.UnityStats.drawCalls+"\nAssembly groups: "+w.pieces.Length+"\nHeadset frame rate is not measured. Desktop prototype only.\n");break;
 case 13:Shot("07-verified-workbench");File.WriteAllText(AtelierEditor.Root+"/Reports/qa-complete.txt","PASS "+checks.Count+" checks");SessionState.SetBool("Atelier.QA",false);return;
 }SessionState.SetInt("Atelier.QAStep",step+1);}catch(Exception error){SessionState.SetBool("Atelier.QA",false);File.WriteAllText(AtelierEditor.Root+"/Reports/qa-error.txt",error.ToString());Debug.LogException(error);}}
 public static void BuildPlayer(){EditorSceneManager.OpenScene(AtelierEditor.Scene);var report=BuildPipeline.BuildPlayer(new BuildPlayerOptions{scenes=new[]{AtelierEditor.Scene},locationPathName=AtelierEditor.Root+"/Builds/Windows/SteamAtelier.exe",target=BuildTarget.StandaloneWindows64,options=BuildOptions.None});File.WriteAllText(AtelierEditor.Root+"/Reports/player-build.txt",report.summary.result+"\n"+report.summary.totalSize+" bytes\nErrors "+report.summary.totalErrors);if(report.summary.result!=BuildResult.Succeeded)throw new Exception("Player build failed");}
}
